import sys
sys.path.insert(0, '.')
from phase0_v2.calibration.audit_helpers import reclassify_condition_c
from phase0_v2.calibration._shared import load_records_filtered
from phase0_v2.conflicts.definitions.disclaimer_first_vs_none import (
    _DISCLAIMER_PHRASES, _DISCLAIMER_HEADER_RE, _WHILE_I_RE,
    _normalize_apostrophes, _find_refusal_end, _PREFIX_LEN,
    _extract_first_n_sentences, _SENTENCE_COUNT
)

FIXED_PHRASES = [p for p in _DISCLAIMER_PHRASES if p != 'simplified overview']

def _text_has_disclaimer_fixed(text):
    lower = text.lower()
    if any(phrase in lower for phrase in FIXED_PHRASES):
        return True
    if _DISCLAIMER_HEADER_RE.search(text):
        return True
    if _WHILE_I_RE.search(text.strip()):
        return True
    return False

def _has_disclaimer_first_fixed(r):
    if not r or not r.strip():
        return False
    text = _normalize_apostrophes(r)
    refusal_end = _find_refusal_end(text)
    if refusal_end is not None:
        remainder = text[refusal_end:]
        if not remainder.strip():
            return False
        prefix_text = remainder[:_PREFIX_LEN]
        sentence_text = _extract_first_n_sentences(remainder, _SENTENCE_COUNT)
        return _text_has_disclaimer_fixed(prefix_text) or _text_has_disclaimer_fixed(sentence_text)
    prefix_text = text[:_PREFIX_LEN]
    sentence_text = _extract_first_n_sentences(text, _SENTENCE_COUNT)
    return _text_has_disclaimer_fixed(prefix_text) or _text_has_disclaimer_fixed(sentence_text)

def _no_disclaimer_fixed(r):
    if not r or not r.strip():
        return True
    return not _has_disclaimer_first_fixed(r)

_, records = load_records_filtered('phase0_v2/data/results/meta-llama_Llama-3.1-8B-Instruct_results.jsonl', 'disclaimer_first_vs_none')
fix = reclassify_condition_c(records, 'disclaimer_first_vs_none', _has_disclaimer_first_fixed, _no_disclaimer_fixed)
print(f'old: {fix["old_labels"]}')
print(f'new: {fix["new_labels"]}')
print(f'changed: {fix["changed"]}')
print(f'contradiction_pct: {fix["contradiction_pct"]:.2f}%')
